toolScript:
// --- Core Application State ---
        const canvas = document.getElementById('main-canvas');
        const ctx = canvas.getContext('2d');
        let baseImage = null; // Background image or rendered PDF page
        let elements = []; // Array of text and image overlays
        let selectedId = null; // Selected element ID

        // PDF document states
        let pdfDoc = null;
        let pdfPageNum = 1;
        let elementsByPage = {}; // Store elements per page: { pageNum: elementsArray }

        // Interaction state
        let isDragging = false;
        let isRotating = false;
        let dragOffsetX = 0;
        let dragOffsetY = 0;

        // Signature drawing states
        const sigCanvas = document.getElementById('signature-canvas');
        const sigCtx = sigCanvas.getContext('2d');
        let isDrawingSig = false;
        let sigLastX = 0;
        let sigLastY = 0;

        // Loaded custom fonts
        let loadedFonts = [];

        // --- Utility Functions ---
        const generateId = () => Math.random().toString(36).substring(2, 9) + Date.now().toString(36);

        function getPointerPos(evt) {
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / rect.width;
            const scaleY = canvas.height / rect.height;

            let clientX = evt.clientX;
            let clientY = evt.clientY;

            if (evt.touches && evt.touches.length > 0) {
                clientX = evt.touches[0].clientX;
                clientY = evt.touches[0].clientY;
            }

            return {
                x: (clientX - rect.left) * scaleX,
                y: (clientY - rect.top) * scaleY
            };
        }

        // --- Tab Management ---
        function switchTab(tabId) {
            const tabs = ['project', 'properties', 'bulk'];
            tabs.forEach(t => {
                const btn = document.getElementById(`tab-btn-${t}`);
                const content = document.getElementById(`tab-content-${t}`);
                if (t === tabId) {
                    btn.classList.add('border-[#EE6C4D]', 'text-white', 'bg-slate-900/50');
                    btn.classList.remove('border-transparent', 'text-slate-400');
                    content.classList.remove('hidden');
                } else {
                    btn.classList.remove('border-[#EE6C4D]', 'text-white', 'bg-slate-900/50');
                    btn.classList.add('border-transparent', 'text-slate-400');
                    content.classList.add('hidden');
                }
            });
        }

        // --- Signature Sketchpad Logic ---
        function openSignatureModal() {
            document.getElementById('signature-modal').classList.remove('hidden');
            document.getElementById('signature-modal').classList.add('flex');
            clearSignatureCanvas();
        }

        function closeSignatureModal() {
            document.getElementById('signature-modal').classList.add('hidden');
            document.getElementById('signature-modal').classList.remove('flex');
        }

        function clearSignatureCanvas() {
            sigCtx.clearRect(0, 0, sigCanvas.width, sigCanvas.height);
            sigCtx.strokeStyle = '#0f172a';
            sigCtx.lineWidth = 3;
            sigCtx.lineCap = 'round';
            sigCtx.lineJoin = 'round';
        }

        // Signature event listeners
        function getSigPointerPos(evt) {
            const rect = sigCanvas.getBoundingClientRect();
            const scaleX = sigCanvas.width / rect.width;
            const scaleY = sigCanvas.height / rect.height;
            let clientX = evt.clientX;
            let clientY = evt.clientY;

            if (evt.touches && evt.touches.length > 0) {
                clientX = evt.touches[0].clientX;
                clientY = evt.touches[0].clientY;
            }
            return {
                x: (clientX - rect.left) * scaleX,
                y: (clientY - rect.top) * scaleY
            };
        }

        function startSigDrawing(e) {
            e.preventDefault();
            isDrawingSig = true;
            const pos = getSigPointerPos(e);
            sigLastX = pos.x;
            sigLastY = pos.y;
        }

        function drawSig(e) {
            if (!isDrawingSig) return;
            e.preventDefault();
            const pos = getSigPointerPos(e);
            sigCtx.beginPath();
            sigCtx.moveTo(sigLastX, sigLastY);
            sigCtx.lineTo(pos.x, pos.y);
            sigCtx.stroke();
            sigLastX = pos.x;
            sigLastY = pos.y;
        }

        function stopSigDrawing() {
            isDrawingSig = false;
        }

        sigCanvas.addEventListener('mousedown', startSigDrawing);
        sigCanvas.addEventListener('mousemove', drawSig);
        window.addEventListener('mouseup', stopSigDrawing);

        sigCanvas.addEventListener('touchstart', startSigDrawing, { passive: false });
        sigCanvas.addEventListener('touchmove', drawSig, { passive: false });
        window.addEventListener('touchend', stopSigDrawing);

        function saveSignature() {
            // Check if user drew anything (we check if there are non-transparent pixels)
            const imgData = sigCtx.getImageData(0, 0, sigCanvas.width, sigCanvas.height);
            let hasDrawing = false;
            for (let i = 3; i < imgData.data.length; i += 4) {
                if (imgData.data[i] > 0) {
                    hasDrawing = true;
                    break;
                }
            }

            if (!hasDrawing) {
                showAlert('Draw Signature', 'Please draw a signature in the box before inserting it.');
                return;
            }

            const dataUrl = sigCanvas.toDataURL('image/png');
            const img = new Image();
            img.onload = () => {
                const w = 200;
                const h = 100;
                const newImgEl = {
                    id: generateId(),
                    type: 'image',
                    x: (canvas.width / 2) - (w / 2),
                    y: (canvas.height / 2) - (h / 2),
                    img: img,
                    baseWidth: img.width,
                    baseHeight: img.height,
                    width: w,
                    height: h,
                    scale: 1,
                    rotation: 0,
                    _width: w, _height: h
                };
                elements.push(newImgEl);
                selectedId = newImgEl.id;
                closeSignatureModal();
                updateUI();
                render();
            };
            img.src = dataUrl;
        }

        // --- Alert Modal ---
        function showAlert(title, message) {
            document.getElementById('alert-title').innerText = title;
            document.getElementById('alert-message').innerText = message;
            document.getElementById('alert-modal').classList.remove('hidden');
            document.getElementById('alert-modal').classList.add('flex');
        }

        function closeAlertModal() {
            document.getElementById('alert-modal').classList.add('hidden');
            document.getElementById('alert-modal').classList.remove('flex');
        }

        // --- Base PDF rendering using pdf.js ---
        async function loadPDFDocument(file) {
            const arrayBuffer = await file.arrayBuffer();
            try {
                const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
                pdfDoc = await loadingTask.promise;
                pdfPageNum = 1;
                elements = [];
                elementsByPage = {};
                selectedId = null;
                document.getElementById('pdf-controls').classList.remove('hidden');
                await renderPDFPage(pdfPageNum);
                updateUI();
            } catch (err) {
                console.error(err);
                showAlert('Error loading PDF', 'Failed to load PDF document. Please make sure it is a valid PDF file.');
            }
        }

        async function renderPDFPage(num) {
            if (!pdfDoc) return;
            try {
                const page = await pdfDoc.getPage(num);
                // Render at high-density scale (2.0)
                const viewport = page.getViewport({ scale: 2.0 });
                const offCanvas = document.createElement('canvas');
                offCanvas.width = viewport.width;
                offCanvas.height = viewport.height;
                const offCtx = offCanvas.getContext('2d');

                await page.render({ canvasContext: offCtx, viewport: viewport }).promise;

                const dataUrl = offCanvas.toDataURL('image/png');
                const img = new Image();
                img.onload = () => {
                    baseImage = img;
                    canvas.width = img.width;
                    canvas.height = img.height;
                    document.getElementById('metric-resolution').innerText = `${canvas.width} x ${canvas.height}`;
                    document.getElementById('pdf-page-indicator').innerText = `Pg ${num} / ${pdfDoc.numPages}`;
                    render();
                };
                img.src = dataUrl;
            } catch (err) {
                console.error(err);
                showAlert('Error rendering page', 'Failed to render the PDF page.');
            }
        }

        async function changePDFPage(dir) {
            if (!pdfDoc) return;
            const newNum = pdfPageNum + dir;
            if (newNum >= 1 && newNum <= pdfDoc.numPages) {
                // Save current elements for the active page
                elementsByPage[pdfPageNum] = elements;

                pdfPageNum = newNum;

                // Retrieve elements for the new page
                elements = elementsByPage[pdfPageNum] || [];
                selectedId = null;

                await renderPDFPage(pdfPageNum);
                updateUI();
            }
        }

        // --- Rendering Engine ---
        let isGridActive = false;

        function render(mode = 'display') {
            const forExport = mode !== 'display';

            // Clear canvas
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            canvas.style.fontVariationSettings = "normal";

            // Draw Base Image (Background)
            if (baseImage) {
                ctx.drawImage(baseImage, 0, 0, canvas.width, canvas.height);
            } else {
                const certType = document.getElementById('certType').value;
                if (certType && certType !== 'custom') {
                    drawVectorTemplateBackground(ctx, canvas, certType);
                } else {
                    if (!forExport) {
                        ctx.fillStyle = '#1e293b'; // Slate 800 placeholder
                        ctx.fillRect(0, 0, canvas.width, canvas.height);
                        if (elements.length === 0) {
                            ctx.fillStyle = '#64748b';
                            ctx.font = 'bold 20px Arial';
                            ctx.textAlign = 'center';
                            ctx.textBaseline = 'middle';
                            ctx.fillText('Upload base image/PDF or select a template to start', canvas.width / 2, canvas.height / 2);
                        }
                    } else {
                        // Export with white background instead of transparency
                        ctx.fillStyle = '#ffffff';
                        ctx.fillRect(0, 0, canvas.width, canvas.height);
                    }
                }
            }

            // Draw Elements
            drawElementsOnCtx(ctx, canvas, elements, forExport);

            // Draw Grid Overlay (display mode only)
            if (!forExport && isGridActive) {
                drawGrid(ctx);
            }

            // Reset
            canvas.style.fontVariationSettings = "normal";
            document.getElementById('metric-layers').innerText = elements.length;
        }

        // Vector Background Presets
        function drawVectorTemplateBackground(c, cv, type) {
            c.fillStyle = '#ffffff';
            c.fillRect(0, 0, cv.width, cv.height);

            const w = cv.width;
            const h = cv.height;

            if (type === 'participant') {
                // Emerald & Gold theme
                c.fillStyle = '#064e3b'; // Emerald dark green
                c.fillRect(0, 0, w, h);

                const pad = Math.floor(w * 0.03);
                c.fillStyle = '#fafdfb';
                c.fillRect(pad, pad, w - pad * 2, h - pad * 2);

                c.strokeStyle = '#EE6C4D'; // Gold/Orange accent
                c.lineWidth = 4;
                const innerPad = pad + 10;
                c.strokeRect(innerPad, innerPad, w - innerPad * 2, h - innerPad * 2);

                c.fillStyle = '#064e3b';
                c.fillRect(innerPad, innerPad, 40, 4);
                c.fillRect(innerPad, innerPad, 4, 40);
                c.fillRect(w - innerPad - 40, innerPad, 40, 4);
                c.fillRect(w - innerPad - 4, innerPad, 4, 40);
                c.fillRect(innerPad, h - innerPad - 4, 40, 4);
                c.fillRect(innerPad, h - innerPad - 40, 4, 40);
                c.fillRect(w - innerPad - 40, h - innerPad - 4, 40, 4);
                c.fillRect(w - innerPad - 4, h - innerPad - 40, 4, 40);

            } else if (type === 'achievement') {
                // Royal Deep Blue & Gold theme
                c.fillStyle = '#1e3a8a'; // Royal blue
                c.fillRect(0, 0, w, h);

                const pad = Math.floor(w * 0.035);
                c.fillStyle = '#fcfdff';
                c.fillRect(pad, pad, w - pad * 2, h - pad * 2);

                c.strokeStyle = '#d97706'; // Gold/Amber
                c.lineWidth = 3;
                const innerPad1 = pad + 8;
                c.strokeRect(innerPad1, innerPad1, w - innerPad1 * 2, h - innerPad1 * 2);

                c.lineWidth = 1;
                const innerPad2 = innerPad1 + 6;
                c.strokeRect(innerPad2, innerPad2, w - innerPad2 * 2, h - innerPad2 * 2);

                // Draw a gold certificate seal
                c.save();
                c.translate(w / 2, h - pad - 60);
                c.beginPath();
                c.arc(0, 0, 35, 0, Math.PI * 2);
                c.fillStyle = '#f59e0b';
                c.fill();
                c.strokeStyle = '#b45309';
                c.lineWidth = 3;
                c.stroke();
                c.fillStyle = '#ffffff';
                c.beginPath();
                c.arc(0, 0, 15, 0, Math.PI * 2);
                c.fill();
                c.restore();
            } else if (type === 'excellence') {
                // Purple & Gold/Dark theme
                c.fillStyle = '#4c1d95'; // Deep purple
                c.fillRect(0, 0, w, h);
                const pad = Math.floor(w * 0.04);
                c.fillStyle = '#fffdfa'; // warm white
                c.fillRect(pad, pad, w - pad * 2, h - pad * 2);

                // Ornate inner border
                c.strokeStyle = '#c026d3'; // Fuchsia accent
                c.lineWidth = 1;
                c.strokeRect(pad + 15, pad + 15, w - pad * 2 - 30, h - pad * 2 - 30);
                c.strokeRect(pad + 20, pad + 20, w - pad * 2 - 40, h - pad * 2 - 40);

                // Badge top center
                c.save();
                c.translate(w / 2, pad + 40);
                c.fillStyle = '#eab308'; // Gold
                c.beginPath();
                c.moveTo(0, -20);
                c.lineTo(15, 10);
                c.lineTo(-15, 10);
                c.closePath();
                c.fill();
                c.restore();
            } else if (type === 'completion') {
                // Minimalist clean look (Slate & Teal)
                c.fillStyle = '#f8fafc'; // light slate
                c.fillRect(0, 0, w, h);

                // Solid teal accent block on the left
                c.fillStyle = '#0f766e'; // Teal 700
                c.fillRect(0, 0, 80, h);

                c.strokeStyle = '#cbd5e1'; // slate-300
                c.lineWidth = 1;
                c.strokeRect(100, 40, w - 140, h - 80);
            }
        }

        // Grid Alignment Overlay
        function toggleGrid() {
            isGridActive = !isGridActive;
            const btn = document.getElementById('btn-toggle-grid');
            if (btn) {
                btn.classList.toggle('bg-slate-600', isGridActive);
                btn.classList.toggle('border-[#EE6C4D]', isGridActive);
                btn.innerHTML = isGridActive ? 
                    '<i class="fa-solid fa-table-cells text-[#EE6C4D]"></i> Hide Alignment Grid' : 
                    '<i class="fa-solid fa-table-cells text-slate-400"></i> Show Alignment Grid';
            }
            render();
        }

        function drawGrid(c) {
            c.save();
            c.strokeStyle = 'rgba(238, 108, 77, 0.15)';
            c.lineWidth = 1;
            c.setLineDash([4, 4]);

            for (let x = 50; x < canvas.width; x += 50) {
                c.beginPath();
                c.moveTo(x, 0);
                c.lineTo(x, canvas.height);
                c.stroke();
            }
            for (let y = 50; y < canvas.height; y += 50) {
                c.beginPath();
                c.moveTo(0, y);
                c.lineTo(canvas.width, y);
                c.stroke();
            }

            c.strokeStyle = 'rgba(238, 108, 77, 0.4)';
            c.lineWidth = 1.5;
            c.setLineDash([]);
            c.beginPath();
            c.moveTo(canvas.width / 2, 0);
            c.lineTo(canvas.width / 2, canvas.height);
            c.stroke();

            c.beginPath();
            c.moveTo(0, canvas.height / 2);
            c.lineTo(canvas.width, canvas.height / 2);
            c.stroke();
            c.restore();
        }

        // Modular helper to draw elements on any canvas context
        function drawElementsOnCtx(targetCtx, targetCanvas, elementsList, forExport) {
            elementsList.forEach(el => {
                targetCtx.save();

                // 1. Setup typography specifications on context
                if (el.type === 'text') {
                    const variationSettings = `"wght" ${el.fontWeight || 400}, "GRAD" ${el.fontGrade || 0}`;
                    targetCanvas.style.fontVariationSettings = variationSettings;

                    const fontStyle = `${el.isItalic ? 'italic ' : ''}${el.fontWeight || 400}`;
                    targetCtx.font = `${fontStyle} ${el.fontSize}px "${el.fontFamily}"`;

                    if ('letterSpacing' in targetCtx) {
                        targetCtx.letterSpacing = `${el.letterSpacing || 0}px`;
                    }

                    const lines = el.text.split('\n');
                    let maxWidth = 0;
                    const lineHeight = el.fontSize * 1.2;

                    lines.forEach(line => {
                        const w = targetCtx.measureText(line).width;
                        if (w > maxWidth) maxWidth = w;
                    });

                    el._width = maxWidth;
                    el._height = lines.length * lineHeight;
                } else if (el.type === 'image') {
                    el._width = el.width;
                    el._height = el.height;
                }

                // 2. Perform rotation transformation
                const cx = el.x + (el._width || 0) / 2;
                const cy = el.y + (el._height || 0) / 2;

                if (el.rotation) {
                    targetCtx.translate(cx, cy);
                    targetCtx.rotate(el.rotation * Math.PI / 180);
                    targetCtx.translate(-cx, -cy);
                }

                // 3. Draw content
                if (el.type === 'text') {
                    targetCtx.textBaseline = 'top';
                    targetCtx.textAlign = 'left'; 
                    targetCtx.fillStyle = el.color;

                    const lines = el.text.split('\n');
                    const lineHeight = el.fontSize * 1.2;

                    // Stroke settings if active
                    const hasStroke = el.strokeWidth && el.strokeWidth > 0;
                    if (hasStroke) {
                        targetCtx.strokeStyle = el.strokeColor || '#000000';
                        targetCtx.lineWidth = el.strokeWidth;
                        targetCtx.lineJoin = 'round';
                        targetCtx.lineCap = 'round';
                    }

                    lines.forEach((line, index) => {
                        const w = targetCtx.measureText(line).width;
                        let lineX = el.x;

                        if (el.textAlign === 'center') {
                            lineX = el.x + (el._width / 2) - (w / 2);
                        } else if (el.textAlign === 'right') {
                            lineX = el.x + el._width - w;
                        }

                        if (hasStroke) {
                            targetCtx.strokeText(line, lineX, el.y + (index * lineHeight));
                        }
                        targetCtx.fillText(line, lineX, el.y + (index * lineHeight));
                    });
                } else if (el.type === 'image') {
                    targetCtx.drawImage(el.img, el.x, el.y, el.width, el.height);
                }

                // 4. Bounding Box & Handles (display mode only)
                if (!forExport && el.id === selectedId) {
                    targetCtx.save();
                    targetCtx.strokeStyle = '#EE6C4D'; // Primary accent orange

                    const rect = targetCanvas.getBoundingClientRect();
                    const scale = targetCanvas.width / rect.width;
                    targetCtx.lineWidth = 2 * scale;
                    targetCtx.setLineDash([6 * scale, 4 * scale]);

                    const pad = 4 * scale;
                    targetCtx.strokeRect(el.x - pad, el.y - pad, (el._width || 0) + (pad * 2), (el._height || 0) + (pad * 2));

                    // Rotation knob
                    const topCenter_x = el.x + (el._width || 0) / 2;
                    const topCenter_y = el.y - pad;
                    const handleLength = 35 * scale;

                    targetCtx.setLineDash([]);
                    targetCtx.beginPath();
                    targetCtx.moveTo(topCenter_x, topCenter_y);
                    targetCtx.lineTo(topCenter_x, topCenter_y - handleLength);
                    targetCtx.stroke();

                    targetCtx.beginPath();
                    targetCtx.arc(topCenter_x, topCenter_y - handleLength, 6 * scale, 0, Math.PI * 2);
                    targetCtx.fillStyle = '#ffffff';
                    targetCtx.fill();
                    targetCtx.stroke();

                    targetCtx.restore();
                }

                targetCtx.restore();
            });

            targetCanvas.style.fontVariationSettings = "normal";
        }

        // --- Input & Pointer Listeners ---
        function handlePointerDown(e) {
            e.preventDefault();
            const pos = getPointerPos(e);
            let hitFound = false;

            // Check elements from top layer downwards
            for (let i = elements.length - 1; i >= 0; i--) {
                const el = elements[i];
                const cx = el.x + (el._width || 0) / 2;
                const cy = el.y + (el._height || 0) / 2;
                const angle = -(el.rotation || 0) * Math.PI / 180;

                const dx = pos.x - cx;
                const dy = pos.y - cy;
                const rx = dx * Math.cos(angle) - dy * Math.sin(angle) + cx;
                const ry = dx * Math.sin(angle) + dy * Math.cos(angle) + cy;

                // Check rotation knob first
                if (el.id === selectedId) {
                    const rect = canvas.getBoundingClientRect();
                    const scale = canvas.width / rect.width;
                    const pad = 4 * scale;
                    const handleLength = 35 * scale;
                    const topCenter_x = el.x + (el._width || 0) / 2;
                    const handle_y = el.y - pad - handleLength;

                    const hitRadius = 15 * scale;
                    if (Math.hypot(rx - topCenter_x, ry - handle_y) <= hitRadius) {
                        isRotating = true;
                        hitFound = true;
                        break;
                    }
                }

                // Check bounds of element
                if (rx >= el.x && rx <= el.x + el._width &&
                    ry >= el.y && ry <= el.y + el._height) {
                    selectedId = el.id;
                    isDragging = true;
                    dragOffsetX = pos.x - el.x;
                    dragOffsetY = pos.y - el.y;
                    hitFound = true;
                    switchTab('properties'); // auto-focus variables
                    break;
                }
            }

            if (!hitFound) {
                selectedId = null;
                isDragging = false;
                isRotating = false;
            }

            updateUI();
            render();
        }

        function handlePointerMove(e) {
            if (!isDragging && !isRotating) return;
            if (!selectedId) return;
            e.preventDefault();

            const pos = getPointerPos(e);
            const el = elements.find(e => e.id === selectedId);
            if (!el) return;

            if (isRotating) {
                const cx = el.x + (el._width || 0) / 2;
                const cy = el.y + (el._height || 0) / 2;
                const angleRad = Math.atan2(pos.y - cy, pos.x - cx);
                let angleDeg = (angleRad * 180 / Math.PI) + 90;
                if (angleDeg < 0) angleDeg += 360;

                el.rotation = Math.round(angleDeg);
                uiElements.rotation.value = el.rotation;
                uiElements.rotationNum.value = el.rotation;
                render();
            } else if (isDragging) {
                let targetX = pos.x - dragOffsetX;
                let targetY = pos.y - dragOffsetY;

                // Alignment Snapping to Canvas Centers
                const cx = (canvas.width / 2) - (el._width / 2);
                const cy = (canvas.height / 2) - (el._height / 2);
                if (Math.abs(targetX - cx) < 12) {
                    targetX = cx;
                }
                if (Math.abs(targetY - cy) < 12) {
                    targetY = cy;
                }

                el.x = targetX;
                el.y = targetY;
                render();
            }
        }

        function handlePointerUp() {
            if (isDragging || isRotating) {
                saveHistory();
            }
            isDragging = false;
            isRotating = false;
        }

        canvas.addEventListener('mousedown', handlePointerDown);
        window.addEventListener('mousemove', handlePointerMove);
        window.addEventListener('mouseup', handlePointerUp);

        canvas.addEventListener('touchstart', handlePointerDown, { passive: false });
        window.addEventListener('touchmove', handlePointerMove, { passive: false });
        window.addEventListener('touchend', handlePointerUp);

        // --- Add Elements ---
        function addText() {
            const fontToUse = loadedFonts.length > 0 ? loadedFonts[loadedFonts.length - 1] : 'Arial';
            const newText = {
                id: generateId(),
                type: 'text',
                x: (canvas.width / 2) - 100,
                y: (canvas.height / 2) - 20,
                text: 'Edit Text Layer',
                fontSize: Math.max(24, Math.floor(canvas.width * 0.04)),
                color: '#EE6C4D',
                fontFamily: fontToUse,
                textAlign: 'left',
                fontWeight: 400,
                fontGrade: 0,
                letterSpacing: 0,
                isItalic: false,
                isDynamic: false,
                rotation: 0,
                strokeWidth: 0,
                strokeColor: '#000000',
                _width: 0, _height: 0
            };
            elements.push(newText);
            selectedId = newText.id;
            saveHistory();
            updateUI();
            render();
        }

        // --- File Inputs & File Handlers ---
        document.getElementById('upload-base').addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (!file) return;

            if (file.type === 'application/pdf') {
                loadPDFDocument(file);
            } else {
                const reader = new FileReader();
                reader.onload = (event) => {
                    const img = new Image();
                    img.onload = () => {
                        baseImage = img;
                        pdfDoc = null;
                        elements = [];
                        elementsByPage = {};
                        selectedId = null;
                        document.getElementById('pdf-controls').classList.add('hidden');
                        document.getElementById('certType').value = 'custom';
                        canvas.width = img.width;
                        canvas.height = img.height;
