        document.getElementById('upload-overlay').addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = (event) => {
                const img = new Image();
                img.onload = () => {
                    let initialScale = 1;
                    if (img.width > canvas.width * 0.4) {
                        initialScale = (canvas.width * 0.4) / img.width;
                    }
                    const w = img.width * initialScale;
                    const h = img.height * initialScale;

                    const newImgEl = {
                        id: generateId(),
                        type: 'image',
                        x: (canvas.width / 2) - (w / 2),
                        y: (canvas.height / 2) - (h / 2),
                        img: img,
                        baseWidth: img.width,
                        baseHeight: img.height,
                        width: w,
                        height: h,
                        scale: initialScale,
                        rotation: 0,
                        _width: w, _height: h
                    };
                    elements.push(newImgEl);
                    selectedId = newImgEl.id;
                    saveHistory();
                    updateUI();
                    render();
                };
                img.src = event.target.result;
            };
            reader.readAsDataURL(file);
            e.target.value = '';
        });

