            const file = e.target.files[0];
            if (!file) return;

            try {
                const buffer = await file.arrayBuffer();
                const safeName = file.name.replace(/[^a-zA-Z0-9]/g, '') + generateId();
                const font = new FontFace(safeName, buffer);

                const loadedFace = await font.load();
                document.fonts.add(loadedFace);
                loadedFonts.push(safeName);
                document.getElementById('metric-fonts').innerText = 4 + loadedFonts.length;

                const select = document.getElementById('prop-font');
                const opt = document.createElement('option');
                opt.value = safeName;
                opt.textContent = file.name;
                select.appendChild(opt);

                if (selectedId) {
                    const el = elements.find(el => el.id === selectedId);
                    if (el && el.type === 'text') {
                        el.fontFamily = safeName;
                        select.value = safeName;
                        saveHistory();
                        render();
                    }
                }
                showAlert('Success', `Custom typography "${file.name}" loaded successfully.`);
            } catch (err) {
                console.error(err);
