        // --- Undo / Redo History stack ---
        let history = [];
        let redoStack = [];

        function saveHistory() {
            if (history.length > 50) history.shift();
            const state = {
                elements: JSON.parse(JSON.stringify(elements)),
                canvasWidth: canvas.width,
                canvasHeight: canvas.height,
                certType: document.getElementById('certType').value,
                selectedId: selectedId
            };
            elements.forEach((el, idx) => {
                if (el.type === 'image') {
                    state.elements[idx]._imgSrc = el.img.src;
                }
            });
            history.push(state);
            redoStack = []; 
            updateUndoRedoButtons();
        }

        function undo() {
            if (history.length <= 1) return;
            const currentState = history.pop();
            redoStack.push(currentState);

            const prevState = history[history.length - 1];
            applyHistoryState(prevState);
        }

        function redo() {
            if (redoStack.length === 0) return;
            const nextState = redoStack.pop();
            history.push(nextState);
            applyHistoryState(nextState);
        }

        function applyHistoryState(state) {
            canvas.width = state.canvasWidth;
            canvas.height = state.canvasHeight;
            document.getElementById('metric-resolution').innerText = `${canvas.width} x ${canvas.height}`;
            document.getElementById('certType').value = state.certType;
            selectedId = state.selectedId;

            elements = [];
            let imagesToLoad = 0;

            state.elements.forEach(el => {
                if (el.type === 'image') {
                    imagesToLoad++;
                    const img = new Image();
                    img.onload = () => {
                        el.img = img;
                        imagesToLoad--;
                        if (imagesToLoad === 0) render();
                    };
                    img.src = el._imgSrc;
                }
                elements.push(el);
            });

            if (imagesToLoad === 0) render();
            updateUI();
            updateUndoRedoButtons();
        }

        function updateUndoRedoButtons() {
            const btnUndo = document.getElementById('btn-undo');
            const btnRedo = document.getElementById('btn-redo');
            if (btnUndo) {
                btnUndo.disabled = history.length <= 1;
                btnUndo.classList.toggle('opacity-50', history.length <= 1);
            }
            if (btnRedo) {
                btnRedo.disabled = redoStack.length === 0;
                btnRedo.classList.toggle('opacity-50', redoStack.length === 0);
            }
        }

        // Keyboard Shortcuts
        window.addEventListener('keydown', (e) => {
            const isMac = /Mac/i.test(navigator.userAgent);
            const modifier = isMac ? e.metaKey : e.ctrlKey;

            if (modifier && e.key.toLowerCase() === 'z') {
                e.preventDefault();
                if (e.shiftKey) {
                    redo();
                } else {
                    undo();
                }
            } else if (modifier && e.key.toLowerCase() === 'y') {
                e.preventDefault();
                redo();
            }
        });

