        function updateUI() {
            const el = elements.find(e => e.id === selectedId);
            if (!el) {
                uiElements.panel.classList.add('hidden');
                uiElements.emptyState.classList.remove('hidden');
                return;
            }

            uiElements.emptyState.classList.add('hidden');
            uiElements.panel.classList.remove('hidden');

            uiElements.rotation.value = el.rotation || 0;
            uiElements.rotationNum.value = el.rotation || 0;

            if (el.type === 'text') {
                uiElements.badge.textContent = 'TEXT LAYER';
                uiElements.textControls.classList.remove('hidden');
                uiElements.imageControls.classList.add('hidden');

                uiElements.text.value = el.text;
                uiElements.color.value = el.color;
                uiElements.colorHex.value = el.color.toUpperCase();
                uiElements.fontSize.value = el.fontSize;
                uiElements.fontFamily.value = el.fontFamily;

                uiElements.fontWeight.value = el.fontWeight || 400;
                uiElements.fontWeightNum.value = el.fontWeight || 400;
                uiElements.fontGrade.value = el.fontGrade || 0;
                uiElements.fontGradeNum.value = el.fontGrade || 0;
                uiElements.letterSpacing.value = el.letterSpacing || 0;
                uiElements.letterSpacingNum.value = el.letterSpacing || 0;
                uiElements.isDynamic.checked = el.isDynamic || false;

                uiElements.strokeWidth.value = el.strokeWidth || 0;
                uiElements.strokeColor.value = el.strokeColor || '#000000';
                uiElements.strokeColorHex.value = (el.strokeColor || '#000000').toUpperCase();

                uiElements.btnItalic.classList.toggle('bg-slate-700', el.isItalic);
                uiElements.btnItalic.classList.toggle('border-[#EE6C4D]', el.isItalic);

                const aligns = { left: uiElements.btnAlignLeft, center: uiElements.btnAlignCenter, right: uiElements.btnAlignRight };
                for (let key in aligns) {
                    aligns[key].classList.toggle('bg-slate-700', el.textAlign === key);
                    aligns[key].classList.toggle('border-[#EE6C4D]', el.textAlign === key);
                }
            } else if (el.type === 'image') {
                uiElements.badge.textContent = 'IMAGE LAYER';
                uiElements.textControls.classList.add('hidden');
                uiElements.imageControls.classList.remove('hidden');

                uiElements.scale.value = el.scale || 1.0;
                uiElements.scaleNum.value = Math.round((el.scale || 1.0) * 100);
            }
        }

