        // Sliders
        function setupSliderPair(slider, numberInput, elProperty, isFloat = false) {
            function updateVal(val) {
                const el = elements.find(el => el.id === selectedId);
                const parsed = isFloat ? parseFloat(val) : parseInt(val);
                if (el) {
                    if (elProperty === 'scale') {
                        el.scale = parsed;
                        el.width = el.baseWidth * parsed;
                        el.height = el.baseHeight * parsed;
                    } else {
                        el[elProperty] = parsed;
                    }
                    render();
                }
            }
            slider.addEventListener('input', (e) => {
                numberInput.value = isFloat ? Math.round(e.target.value * 100) : e.target.value;
                updateVal(e.target.value);
            });
            slider.addEventListener('change', () => {
                saveHistory();
            });
            numberInput.addEventListener('change', (e) => {
                const val = isFloat ? (parseFloat(e.target.value) / 100 || 1.0) : parseInt(e.target.value);
                slider.value = val;
                updateVal(slider.value);
                saveHistory();
            });
        }

        setupSliderPair(uiElements.fontWeight, uiElements.fontWeightNum, 'fontWeight');
        setupSliderPair(uiElements.fontGrade, uiElements.fontGradeNum, 'fontGrade');
        setupSliderPair(uiElements.letterSpacing, uiElements.letterSpacingNum, 'letterSpacing');
        setupSliderPair(uiElements.scale, uiElements.scaleNum, 'scale', true);
        setupSliderPair(uiElements.rotation, uiElements.rotationNum, 'rotation');

        // Typography styling modifiers
        function toggleTextStyle(style) {
            const el = elements.find(el => el.id === selectedId);
            if (el && el.type === 'text') {
                if (style === 'italic') {
                    el.isItalic = !el.isItalic;
                }
                saveHistory();
                updateUI();
                render();
            }
        }

        function setTextAlign(alignment) {
            const el = elements.find(el => el.id === selectedId);
            if (el && el.type === 'text') {
                el.textAlign = alignment;
                saveHistory();
                updateUI();
                render();
            }
        }

        function centerElement(dir) {
            const el = elements.find(el => el.id === selectedId);
            if (!el) return;
            if (dir === 'horizontal') {
                el.x = (canvas.width / 2) - (el._width / 2);
            } else if (dir === 'vertical') {
                el.y = (canvas.height / 2) - (el._height / 2);
            }
            saveHistory();
            render();
        }

        // Layer sorting
        function moveLayerUp() {
            if (!selectedId) return;
            const idx = elements.findIndex(el => el.id === selectedId);
            if (idx > -1 && idx < elements.length - 1) {
                const temp = elements[idx];
                elements[idx] = elements[idx + 1];
                elements[idx + 1] = temp;
                saveHistory();
                render();
            }
        }

        // Layer sorting
        function moveLayerDown() {
            if (!selectedId) return;
            const idx = elements.findIndex(el => el.id === selectedId);
            if (idx > 0) {
                const temp = elements[idx];
                elements[idx] = elements[idx - 1];
                elements[idx - 1] = temp;
                saveHistory();
                render();
            }
        }

        function deleteSelected() {
            if (!selectedId) return;
            elements = elements.filter(el => el.id !== selectedId);
            selectedId = null;
            saveHistory();
            updateUI();
            render();
        }

        function duplicateSelected() {
            if (!selectedId) return;
            const targetIndex = elements.findIndex(el => el.id === selectedId);
            if (targetIndex > -1) {
                const targetEl = elements[targetIndex];
                const clone = JSON.parse(JSON.stringify(targetEl));
                clone.id = generateId();
                clone.x += 20;
                clone.y += 20;
                if (clone.type === 'image') {
                    clone.img = targetEl.img; // keep image reference
                }
                elements.push(clone);
                selectedId = clone.id;
                saveHistory();
                updateUI();
                render();
            }
        }

        function insertVariable(variableName) {
            if (!selectedId) return;
            const targetEl = elements.find(el => el.id === selectedId);
            if (targetEl && targetEl.type === 'text') {
                targetEl.text += (targetEl.text.length > 0 ? ' ' : '') + variableName;
                document.getElementById('prop-text').value = targetEl.text;
                saveHistory();
                render();
            }
        }

        function requestClearCanvas() {
            if (elements.length > 0 || baseImage || pdfDoc) {
                if (!confirm('Are you sure you want to clear the workspace? This will reset everything.')) {
                    return;
                }
            }
            elements = [];
            elementsByPage = {};
            baseImage = null;
            pdfDoc = null;
            selectedId = null;
            document.getElementById('pdf-controls').classList.add('hidden');
            document.getElementById('certType').value = 'custom';
            document.getElementById('metric-resolution').innerText = "800 x 600";
            canvas.width = 800;
            canvas.height = 600;
            saveHistory();
            updateUI();
            render();
        }

        // --- Export & Download Functions ---
        function triggerDownload(url, filename) {
            const link = document.createElement('a');
            link.href = url;
            link.download = filename;
            document.body.appendChild(link);
            link.click();
            setTimeout(() => {
                document.body.removeChild(link);
            }, 100);
        }

        function getCleanExportData() {
            const prevSelected = selectedId;
            selectedId = null;
            render('export');
            const dataUrl = canvas.toDataURL('image/png');
            selectedId = prevSelected;
            render();
            return dataUrl;
        }

        function downloadImage() {
            const dataUrl = getCleanExportData();
            triggerDownload(dataUrl, `design_${Date.now()}.png`);
        }

        async function downloadPdfDirect() {
            const prevSelected = selectedId;
            selectedId = null;

            if (pdfDoc) {
                elementsByPage[pdfPageNum] = elements;
            }

            const btn = document.querySelector('button[onclick="downloadPdfDirect()"]');
            const originalHTML = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = `<i class="fa-solid fa-spinner animate-spin"></i> Exporting PDF...`;

            try {
                const { jsPDF } = window.jspdf;
                let pdf = null;

                if (pdfDoc) {
                    for (let num = 1; num <= pdfDoc.numPages; num++) {
                        const page = await pdfDoc.getPage(num);
                        const viewport = page.getViewport({ scale: 2.0 });

                        const tempCanvas = document.createElement('canvas');
                        tempCanvas.width = viewport.width;
                        tempCanvas.height = viewport.height;
                        const tempCtx = tempCanvas.getContext('2d');

                        await page.render({ canvasContext: tempCtx, viewport: viewport }).promise;

                        const pageElements = elementsByPage[num] || [];
                        drawElementsOnCtx(tempCtx, tempCanvas, pageElements, true);

                        const orientation = tempCanvas.width > tempCanvas.height ? 'l' : 'p';
                        if (!pdf) {
                            pdf = new jsPDF({
                                orientation: orientation,
                                unit: 'px',
                                format: [tempCanvas.width, tempCanvas.height],
                                hotfixes: ["px_scaling"]
                            });
                        } else {
                            pdf.addPage([tempCanvas.width, tempCanvas.height], orientation);
                        }

                        const imgData = tempCanvas.toDataURL('image/png');
                        pdf.addImage(imgData, 'PNG', 0, 0, tempCanvas.width, tempCanvas.height);
                    }
                } else {
                    render('export');
                    const orientation = canvas.width > canvas.height ? 'l' : 'p';
                    pdf = new jsPDF({
                        orientation: orientation,
                        unit: 'px',
                        format: [canvas.width, canvas.height],
                        hotfixes: ["px_scaling"]
                    });
                    const imgData = canvas.toDataURL('image/png');
                    pdf.addImage(imgData, 'PNG', 0, 0, canvas.width, canvas.height);
                }

                const pdfBlob = pdf.output('blob');
                const blobUrl = URL.createObjectURL(pdfBlob);
                triggerDownload(blobUrl, `document_${Date.now()}.pdf`);
            } catch (err) {
                console.error(err);
                showAlert('Error exporting PDF', 'An error occurred during PDF generation.');
            } finally {
                btn.disabled = false;
                btn.innerHTML = originalHTML;
                selectedId = prevSelected;
                render();
            }
        }

        // CSV parsing helper
        function parseBulkData(text) {
            const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 0);
            if (lines.length === 0) return [];

            const firstLine = lines[0];
            let delimiter = null;
            if (firstLine.includes('\t')) {
                delimiter = '\t';
            } else if (firstLine.includes(',')) {
                delimiter = ',';
            } else if (firstLine.includes(';')) {
                delimiter = ';';
            }

            if (!delimiter) {
                return lines.map(line => ({ 'Name': line }));
            }

            const headers = firstLine.split(delimiter).map(h => h.trim().replace(/^["']|["']$/g, ''));

            if (lines.length <= 1) {
                return [{ 'Name': firstLine }];
            }

            const dataRows = [];
            for (let i = 1; i < lines.length; i++) {
                const rowText = lines[i];
                let cols = [];
                if (delimiter === ',') {
                    let matches = rowText.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
                    if (matches && matches.length === headers.length) {
                        cols = matches.map(c => c.trim().replace(/^["']|["']$/g, ''));
                    } else {
                        cols = rowText.split(',').map(c => c.trim().replace(/^["']|["']$/g, ''));
                    }
                } else {
                    cols = rowText.split(delimiter).map(c => c.trim().replace(/^["']|["']$/g, ''));
                }

                const rowData = {};
                headers.forEach((header, index) => {
                    rowData[header] = cols[index] !== undefined ? cols[index] : '';
                });
                if (rowData['Name'] === undefined && cols[0] !== undefined) {
                    rowData['Name'] = cols[0];
                }
                dataRows.push(rowData);
            }
            return dataRows;
        }

        // Offscreen renderer for direct bulk drawing
        async function renderOffscreen(participantData = null) {
            const tempCanvas = document.createElement('canvas');
            tempCanvas.width = canvas.width;
            tempCanvas.height = canvas.height;
            const tempCtx = tempCanvas.getContext('2d');

            const certType = document.getElementById('certType').value;
            if (baseImage) {
                tempCtx.drawImage(baseImage, 0, 0, tempCanvas.width, tempCanvas.height);
            } else if (certType && certType !== 'custom') {
                drawVectorTemplateBackground(tempCtx, tempCanvas, certType);
            } else {
                tempCtx.fillStyle = '#ffffff';
                tempCtx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
            }

            const tempElements = JSON.parse(JSON.stringify(elements));
            elements.forEach((el, idx) => {
                if (el.type === 'image') {
                    tempElements[idx].img = el.img;
                }
            });

            if (participantData) {
                tempElements.forEach(el => {
                    if (el.type === 'text') {
                        if (el.isDynamic && participantData['Name'] !== undefined) {
                            el.text = participantData['Name'];
                        } else {
                            let txt = el.text;
                            for (let key in participantData) {
                                const regex = new RegExp(`{{\\s*${key}\\s*}}`, 'gi');
                                txt = txt.replace(regex, participantData[key]);
                            }
                            el.text = txt;
                        }
                    }
                });
            }

            drawElementsOnCtx(tempCtx, tempCanvas, tempElements, true);
            return tempCanvas;
        }

        // --- Bulk Generation Engine ---
        async function generateBulkCertificates() {
            const bulkText = document.getElementById('bulkNames').value.trim();
            if (!bulkText) {
                showAlert('Generator Warning', 'Please provide a list of participant names or a CSV (one per line).');
                return;
            }

            if (pdfDoc) {
                elementsByPage[pdfPageNum] = elements;
            }

            const participantRows = parseBulkData(bulkText);
            if (participantRows.length === 0) {
                showAlert('Generator Warning', 'Could not parse any recipient rows. Check your input formatting.');
                return;
            }

            let dynamicPageNum = 1;
            if (pdfDoc) {
                let found = false;
                for (let num = 1; num <= pdfDoc.numPages; num++) {
                    const pageEls = elementsByPage[num] || [];
                    if (pageEls.some(el => el.type === 'text' && (el.isDynamic || el.text.includes('{{')))) {
                        dynamicPageNum = num;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    showAlert('Warning', 'No dynamic text placeholders or variables like {{Name}} found on your PDF layers.');
                }
            } else {
                const hasVariable = elements.some(el => el.type === 'text' && (el.isDynamic || el.text.includes('{{')));
                if (!hasVariable) {
                    showAlert('Missing Variable Placeholder', 'Please select or add a text layer, configure its text (e.g. {{Name}}), and mark the checkbox: "Mark as Name Placeholder" so the generator knows which text layers to replace.');
                    return;
                }
            }

            const format = document.getElementById('bulkFormat').value;
            const prevSelected = selectedId;
            selectedId = null;

            const zip = new JSZip();
            const { jsPDF } = window.jspdf;

            const btn = document.querySelector('button[onclick="generateBulkCertificates()"]');
            const originalHTML = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = `<i class="fa-solid fa-spinner animate-spin"></i> Rendering ${participantRows.length} files...`;

            try {
                await document.fonts.ready;

                for (let i = 0; i < participantRows.length; i++) {
                    const participant = participantRows[i];
                    const safeName = (participant['Name'] || `recipient_${i + 1}`).trim().replace(/[^a-zA-Z0-9]/g, '_');

                    if (pdfDoc && format === 'pdf') {
                        let pdf = null;
                        for (let num = 1; num <= pdfDoc.numPages; num++) {
                            const page = await pdfDoc.getPage(num);
                            const viewport = page.getViewport({ scale: 2.0 });
                            const tempCanvas = document.createElement('canvas');
                            tempCanvas.width = viewport.width;
                            tempCanvas.height = viewport.height;
                            const tempCtx = tempCanvas.getContext('2d');

                            await page.render({ canvasContext: tempCtx, viewport: viewport }).promise;

                            const pageEls = elementsByPage[num] || [];
                            const tempPageEls = JSON.parse(JSON.stringify(pageEls));
                            pageEls.forEach((el, idx) => {
                                if (el.type === 'image') tempPageEls[idx].img = el.img;
                            });

                            tempPageEls.forEach(el => {
                                if (el.type === 'text') {
                                    if (el.isDynamic && participant['Name'] !== undefined) {
                                        el.text = participant['Name'];
                                    } else {
                                        let txt = el.text;
                                        for (let key in participant) {
                                            const regex = new RegExp(`{{\\s*${key}\\s*}}`, 'gi');
                                            txt = txt.replace(regex, participant[key]);
                                        }
                                        el.text = txt;
                                    }
                                }
                            });

                            drawElementsOnCtx(tempCtx, tempCanvas, tempPageEls, true);

                            const orientation = tempCanvas.width > tempCanvas.height ? 'l' : 'p';
                            if (!pdf) {
                                pdf = new jsPDF({
                                    orientation: orientation,
                                    unit: 'px',
                                    format: [tempCanvas.width, tempCanvas.height],
                                    hotfixes: ["px_scaling"]
                                });
                            } else {
                                pdf.addPage([tempCanvas.width, tempCanvas.height], orientation);
                            }

                            const imgData = tempCanvas.toDataURL('image/png');
                            pdf.addImage(imgData, 'PNG', 0, 0, tempCanvas.width, tempCanvas.height);
                        }
                        const pdfBlob = pdf.output('blob');
                        zip.file(`${safeName}.pdf`, pdfBlob);

                    } else if (pdfDoc && format === 'png') {
                        const page = await pdfDoc.getPage(dynamicPageNum);
                        const viewport = page.getViewport({ scale: 2.0 });
                        const tempCanvas = document.createElement('canvas');
                        tempCanvas.width = viewport.width;
                        tempCanvas.height = viewport.height;
                        const tempCtx = tempCanvas.getContext('2d');

                        await page.render({ canvasContext: tempCtx, viewport: viewport }).promise;

                        const pageEls = elementsByPage[dynamicPageNum] || [];
                        const tempPageEls = JSON.parse(JSON.stringify(pageEls));
                        pageEls.forEach((el, idx) => {
                            if (el.type === 'image') tempPageEls[idx].img = el.img;
                        });

                        tempPageEls.forEach(el => {
                            if (el.type === 'text') {
                                if (el.isDynamic && participant['Name'] !== undefined) {
                                    el.text = participant['Name'];
                                } else {
                                    let txt = el.text;
                                    for (let key in participant) {
                                        const regex = new RegExp(`{{\\s*${key}\\s*}}`, 'gi');
                                        txt = txt.replace(regex, participant[key]);
                                    }
                                    el.text = txt;
                                }
                            }
                        });

                        drawElementsOnCtx(tempCtx, tempCanvas, tempPageEls, true);
                        const imgDataUrl = tempCanvas.toDataURL('image/png');
                        const base64Data = imgDataUrl.split(',')[1];
                        zip.file(`${safeName}.png`, base64Data, { base64: true });

                    } else {
                        const tempCanvas = await renderOffscreen(participant);
                        if (format === 'pdf') {
                            const orientation = tempCanvas.width > tempCanvas.height ? 'l' : 'p';
                            const pdf = new jsPDF({
                                orientation: orientation,
                                unit: 'px',
                                format: [tempCanvas.width, tempCanvas.height],
                                hotfixes: ["px_scaling"]
                            });
                            const imgData = tempCanvas.toDataURL('image/png');
                            pdf.addImage(imgData, 'PNG', 0, 0, tempCanvas.width, tempCanvas.height);
                            const pdfBlob = pdf.output('blob');
                            zip.file(`${safeName}.pdf`, pdfBlob);
                        } else {
                            const imgDataUrl = tempCanvas.toDataURL('image/png');
                            const base64Data = imgDataUrl.split(',')[1];
                            zip.file(`${safeName}.png`, base64Data, { base64: true });
                        }
                    }
                }

                const content = await zip.generateAsync({ type: 'blob' });
                const zipUrl = URL.createObjectURL(content);
                triggerDownload(zipUrl, `bulk_export_${Date.now()}.zip`);

                showAlert('Success', `Generated zip archive containing ${participantRows.length} files.`);
            } catch (err) {
                console.error(err);
                showAlert('Error', 'An error occurred during bulk generation.');
            } finally {
                btn.disabled = false;
                btn.innerHTML = originalHTML;
                selectedId = prevSelected;
                render();
            }
        }

        // Initialize editor state and save initial history
        saveHistory();
        updateUI();
        render();
